module package_manager(input clk, input rst_n, input start, input [2:0] pkg_idx, input [79:0] pkg_name, input [79:0] dep_name, input dep_valid, input def_done, input [3:0] n_pkgs, output reg [79:0] result_name, output reg result_valid, output reg done, output reg error); reg [7:0] installed [8]; reg [2:0] in_degree [8]; reg [79:0] package_names [8]; reg [7:0] dependency_exists [8][8]; reg [7:0] dependents [8][8]; reg [3:0] n_pkgs_reg; reg [3:0] current_pkg; reg [3:0] dep_count [8]; reg [7:0] next_install; reg [7:0] selected_package; reg processing_done; reg [2:0] state; always @(posedge clk) begin if (!rst_n) begin installed <= 0; in_degree <= 0; package_names <= 0; dependency_exists <= 0; dependents <= 0; n_pkgs_reg <= 0; current_pkg <= 0; dep_count <= 0; next_install <= 0; selected_package <= 0; processing_done <= 0; state <= 0; end else begin if (state == 0) begin if (start) begin n_pkgs_reg <= n_pkgs; current_pkg <= 0; state <= 1; end end else if (state == 1) begin if (pkg_idx == current_pkg) begin package_names[current_pkg] <= pkg_name; if (dep_valid) begin integer idx; idx = -1; for (int i=0; i < n_pkgs_reg; i++) begin if (package_names[i] == dep_name) begin idx = i; break; end end if (idx != -1 && idx < 8 && dep_count[current_pkg] < 5 && !dependency_exists[current_pkg][idx]) begin dependency_exists[current_pkg][idx] <= 1; in_degree[current_pkg] <= in_degree[current_pkg] + 1; dependents[idx][current_pkg] <= 1; dep_count[current_pkg] <= dep_count[current_pkg] + 1; end end if (def_done) begin current_pkg <= current_pkg + 1; if (current_pkg == n_pkgs_reg) state <= 2; end end end else if (state == 2) begin if (!processing_done) begin reg [7:0] min_pkg; min_pkg <= 8'hFF; reg [79:0] min_name; min_name <= 0; for (int i=0; i < n_pkgs_reg; i++) begin if (!installed[i] && in_degree[i] == 0) begin if (min_pkg > i || (min_pkg == 8'hFF && i < 8)) begin min_pkg <= i; min_name <= package_names[i]; end end end if (min_pkg != 8'hFF) begin selected_package <= min_pkg; result_name <= min_name; result_valid <= 1; next_install <= min_pkg; end else begin if (all_installed) begin processing_done <= 1; done <= 1; result_valid <= 0; end else begin error <= 1; done <= 1; end end if (next_install != 0) begin installed[next_install] <= 1; for (int j=0; j < 8; j++) begin if (dependents[next_install][j] && !installed[j]) begin in_degree[j] <= in_degree[j] - 1; end end next_install <= 0; end endmodule endmodule endmodule